import csv
import datetime as dt
import re
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

DATASET = "/app/dataset"


def _pesel_valid(pesel: str) -> bool:
    if not re.fullmatch(r"\d{11}", pesel):
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    s = sum(int(pesel[i]) * weights[i] for i in range(10))
    return (10 - s % 10) % 10 == int(pesel[10])


def _parse_date(value: str):
    try:
        return dt.date.fromisoformat(value.strip())
    except ValueError:
        return None


def _first_weekday_of_month(year: int, month: int, weekday: int) -> dt.date:
    d = dt.date(year, month, 1)
    return d + dt.timedelta(days=(weekday - d.weekday()) % 7)


def answer() -> dict[str, list[int]]:
    # Employees: hourly rate per valid PESEL.
    rates = {}
    with open(f"{DATASET}/employees.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            pesel = row["PESEL"].strip()
            if _pesel_valid(pesel):
                rates[pesel] = Decimal(row["hourly_rate"].strip())

    # Tasks: bonus per completed task.
    task_pay = {}
    with open(f"{DATASET}/tasks.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            task_pay[int(row["task_id"])] = Decimal(row["pay_per_completion"])

    with open(f"{DATASET}/timesheet.csv", newline="", encoding="utf-8") as f:
        raw = list(csv.DictReader(f))

    # Billing periods start on the weekday of the earliest valid record.
    dates = [d for d in (_parse_date(r["date"]) for r in raw) if d is not None]
    anchor_weekday = min(dates).weekday()

    def billing_month(d: dt.date) -> tuple[int, int]:
        start = _first_weekday_of_month(d.year, d.month, anchor_weekday)
        if d >= start:
            return d.year, d.month
        prev = d.replace(day=1) - dt.timedelta(days=1)
        return prev.year, prev.month

    seen = set()
    hours = defaultdict(Decimal)
    bonus = defaultdict(Decimal)
    for r in raw:
        pesel = r["employee_id"].strip()
        # Unknown / invalid PESELs (ghost entries) have no rate -> excluded.
        if pesel not in rates:
            continue
        # Impossible dates (e.g. 2025-04-31) are inserted records -> excluded.
        d = _parse_date(r["date"])
        if d is None:
            continue
        # Duplicated records (identical apart from id) are counted once.
        key = tuple(v.strip() for k, v in r.items() if k != "id")
        if key in seen:
            continue
        seen.add(key)

        h = Decimal(r["hours_worked"].strip())
        if h < 0 or h > 24:
            continue
        # Malformed task lists (missing brackets) are parsed leniently;
        # unknown task ids earn no bonus; bonus is recomputed from tasks.csv.
        task_ids = {int(t) for t in re.findall(r"\d+", r["performed_tasks"])}
        task_bonus = sum((task_pay[t] for t in task_ids if t in task_pay),
                         Decimal(0))

        month = billing_month(d)
        hours[(pesel, month)] += h
        bonus[(pesel, month)] += task_bonus

    result = defaultdict(list)
    for (pesel, month) in sorted(hours, key=lambda k: (k[0], k[1])):
        total = hours[(pesel, month)] * rates[pesel] + bonus[(pesel, month)]
        result[pesel].append(
            int(total.quantize(Decimal("1"), rounding=ROUND_HALF_UP)))
    return dict(result)


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

